import { getScaleById } from '../data/scales';
import { parseChord, pitchClassOf } from '../utils/chordMath';

export { parseChord, pitchClassOf };

const NOTES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

export type TargetNoteRole = 'root' | 'chordTone' | 'tension' | 'passing' | 'outside';
export type BeatStrength = 'strong' | 'weak';

export interface TargetNote {
  pitch: string;
  pitchClass: number;
  role: TargetNoteRole;
  beatStrength: BeatStrength;
}

const tensionIntervalsFor = (quality: string): Set<number> => {
  if (quality.includes('maj7')) return new Set([2, 6, 9]);
  if (quality.includes('m7') || quality.startsWith('m')) return new Set([2, 5, 9]);
  if (quality.includes('7')) return new Set([1, 2, 3, 5, 6, 8, 9]);
  return new Set([2, 5, 9]);
};

export function getTargetNotes(
  chordName: string,
  scaleId: string,
  beatStrength: BeatStrength = 'weak',
  scaleRoot?: string,
): TargetNote[] {
  const chord = parseChord(chordName);
  if (!chord) throw new RangeError(`Unsupported chord: ${chordName}`);
  const scale = getScaleById(scaleId);
  const scaleTonic = scaleRoot === undefined ? chord.root : pitchClassOf(scaleRoot);
  if (scaleTonic === null) throw new RangeError(`Unsupported scale root: ${scaleRoot}`);
  const scalePitchClasses = new Set(scale.intervals.map(interval => (interval + scaleTonic) % 12));
  const chordPitchClasses = new Set(chord.intervals.map(interval => (interval + chord.root) % 12));
  const tensions = tensionIntervalsFor(chord.quality);

  return NOTES.map((pitch, pitchClass) => {
    let role: TargetNoteRole = 'outside';
    const interval = (pitchClass - chord.root + 12) % 12;

    if (pitchClass === chord.root) role = 'root';
    else if (chordPitchClasses.has(pitchClass)) role = 'chordTone';
    else if (scalePitchClasses.has(pitchClass)) {
      role = beatStrength === 'weak' && tensions.has(interval) ? 'tension' : 'passing';
    }

    return { pitch, pitchClass, role, beatStrength };
  });
}
