import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type React from 'react';
import * as Tone from 'tone';
import { useEarTrainingAudio } from '../../hooks/useEarTrainingAudio';
import { audioManager } from '../../services/AudioManager';
import { generateEchoPhrase, type MelodyNote } from '../../engines/PhraseEchoEngine';
import { getChordScaleRecommendations } from '../../data/chordScaleMap';
import { getScaleById } from '../../data/scales';
import { parseChord } from '../../engines/TargetNoteEngine';

const NOTES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
const CHORD_INTERVAL_LABELS = ['1', 'b2', '2', 'b3', '3', '4', 'b5', '5', 'b6', '6', 'b7', '7'];
const PRESETS = [
  { id: 'ii-v-i', en: 'Jazz · ii–V–I / iiø–V–i', ru: 'Джаз · ii–V–I / iiø–V–i', steps: [[2, 'm7'], [7, '7'], [0, 'maj7'], [0, 'maj7']] },
  { id: 'blues', en: 'Blues · I–IV–V', ru: 'Блюз · I–IV–V', steps: [[0, '7'], [5, '7'], [0, '7'], [7, '7']] },
  { id: 'rock', en: 'Rock · i–VI–III–VII', ru: 'Рок · i–VI–III–VII', steps: [[0, 'm'], [8, ''], [3, ''], [10, '']] },
  { id: 'metal', en: 'Metal · i–iv–v', ru: 'Метал · i–iv–v', steps: [[0, 'm'], [5, 'm'], [7, 'm'], [3, '']] },
  { id: 'funk', en: 'Funk · i7 groove', ru: 'Фанк · грув на i7', steps: [[0, 'm7'], [0, 'm7'], [5, '7'], [0, 'm7']] },
  { id: 'neo-soul', en: 'Neo-soul · Imaj7–IVmaj7', ru: 'Нео-соул · Imaj7–IVmaj7', steps: [[0, 'maj7'], [5, 'maj7'], [3, 'm7'], [7, '7']] },
  { id: 'minor-rock', en: 'Minor rock · i–VII–VI–VII', ru: 'Минорный рок · i–VII–VI–VII', steps: [[0, 'm'], [10, ''], [8, ''], [10, '']] },
  { id: 'dorian', en: 'Dorian · i7–IV7', ru: 'Дорийский · i7–IV7', steps: [[0, 'm7'], [5, '7'], [0, 'm7'], [5, '7']] },
] as const;

const makeProgression = (key: string, presetId: string, scaleId: string): string[] => {
  const preset = PRESETS.find(item => item.id === presetId) ?? PRESETS[0];
  const root = NOTES.indexOf(key);
  const scale = getScaleById(scaleId);
  const isMinor = scale.intervals.includes(3) && !scale.intervals.includes(4);
  const steps = presetId === 'ii-v-i' && isMinor
    ? [[2, 'm7b5'], [7, '7'], [0, 'm7'], [0, 'm7']] as const
    : preset.steps;
  return steps.map(([offset, quality]) => `${NOTES[(root + offset) % 12]}${quality}`);
};

const getRoleLabel = (role: string, locale: string) => {
  const ru: Record<string, string> = {
    root: 'Тоника', chordTone: 'Аккордовый тон', tension: 'Напряжение',
    passing: 'Проходящая', outside: 'Вне гаммы',
  };
  const en: Record<string, string> = {
    root: 'Root', chordTone: 'Chord tone', tension: 'Tension',
    passing: 'Passing tone', outside: 'Outside scale',
  };
  return (locale === 'ru' ? ru : en)[role] ?? role;
};

interface PracticeModeProps {
  keyNote: string;
  scaleId: string;
  locale: string;
  onScaleChange: (scaleId: string, root?: string) => void;
  onChordChange: (chord: string) => void;
  targetPosition: number;
  showPassingNotes: boolean;
  onTargetPositionChange: (position: number) => void;
  onShowPassingNotesChange: (show: boolean) => void;
}

const PracticeMode: React.FC<PracticeModeProps> = ({
  keyNote, scaleId, locale, onScaleChange, onChordChange,
  targetPosition, showPassingNotes, onTargetPositionChange, onShowPassingNotesChange,
}) => {
  const isRu = locale === 'ru';
  const [presetId, setPresetId] = useState<string>('ii-v-i');
  const [progression, setProgression] = useState<string[]>(() => makeProgression(keyNote, 'ii-v-i', scaleId));
  const [activeBar, setActiveBar] = useState(0);
  const [isEditingProgression, setIsEditingProgression] = useState(false);
  const [isBackingPlaying, setIsBackingPlaying] = useState(false);
  const [backingError, setBackingError] = useState('');
  const [backingLevel, setBackingLevel] = useState(0.75);
  const [practiceBpm, setPracticeBpm] = useState(70);
  const [level, setLevel] = useState(1);
  const [phrase, setPhrase] = useState<MelodyNote[]>([]);
  const [phrasePlaying, setPhrasePlaying] = useState(false);
  const [recordingAnswer, setRecordingAnswer] = useState(false);
  const [answerResult, setAnswerResult] = useState('');
  const phraseTimers = useRef<number[]>([]);
  const answerRecordingRef = useRef(false);
  const wasRecordingRef = useRef(false);
  const { isRecording, error: microphoneError, detectedNotes, startRecording, stopRecording } = useEarTrainingAudio();

  const activeChord = progression[activeBar] ?? progression[0];
  const parsedChord = parseChord(activeChord);
  const chordQuality = parsedChord?.quality ?? '';
  const chordNoteNames = parsedChord
    ? parsedChord.intervals.map(interval => NOTES[(parsedChord.root + interval) % 12])
    : [];
  const recommendations = useMemo(() => getChordScaleRecommendations(chordQuality), [chordQuality]);

  useEffect(() => {
    onChordChange(activeChord);
  }, [activeChord, onChordChange]);

  useEffect(() => {
    if (presetId !== 'custom') {
      const next = makeProgression(keyNote, presetId, scaleId);
      setProgression(next);
      setActiveBar(0);
    }
  }, [keyNote, presetId, scaleId]);

  useEffect(() => {
    if (isBackingPlaying) {
      audioManager.stopBackingTrack();
      audioManager.playBackingTrack(progression, practiceBpm, {
        loop: true,
        backingLevel,
        onBarChange: setActiveBar,
      }).catch(error => {
        setBackingError(error instanceof Error ? error.message : String(error));
        setIsBackingPlaying(false);
      });
    } else {
      audioManager.stopBackingTrack();
    }
    return () => audioManager.stopBackingTrack();
  }, [backingLevel, isBackingPlaying, progression, practiceBpm]);

  useEffect(() => {
    const seed = `${Date.now()}-${activeChord}-${scaleId}-${level}`;
    setPhrase(generateEchoPhrase(activeChord, scaleId, level, seed, targetPosition));
    setAnswerResult('');
  }, [activeChord, scaleId, level, targetPosition]);

  useEffect(() => {
    if (isRecording) wasRecordingRef.current = true;
    if (answerRecordingRef.current && microphoneError) {
      answerRecordingRef.current = false;
      wasRecordingRef.current = false;
      setRecordingAnswer(false);
      setAnswerResult(microphoneError);
      return;
    }
    if (answerRecordingRef.current && wasRecordingRef.current && !isRecording) {
      wasRecordingRef.current = false;
      answerRecordingRef.current = false;
      setRecordingAnswer(false);
      const expected = phrase.filter(note => !note.isRest);
      if (detectedNotes.length === 0) {
        setAnswerResult(isRu ? 'Ноты не распознаны. Попробуйте сыграть чуть громче и повторить запись.' : 'No notes detected. Try playing louder and record again.');
        return;
      }

      let matched = 0;
      let expectedIndex = 0;
      for (const detected of detectedNotes) {
        while (expectedIndex < expected.length && detected.note !== expected[expectedIndex].pitchClass) {
          expectedIndex++;
        }
        if (expectedIndex < expected.length) {
          matched++;
          expectedIndex++;
        }
      }
      const noteScore = Math.round((matched / Math.max(1, expected.length)) * 100);
      let phraseBeat = 0;
      const expectedBeatStarts = phrase.flatMap(note => {
        const beatStart = phraseBeat;
        phraseBeat += note.durationBeats;
        return note.isRest ? [] : [beatStart];
      });
      const expectedIntervals = expectedBeatStarts.slice(1).map((beatStart, index) =>
        (beatStart - expectedBeatStarts[index]) * 60 / practiceBpm,
      );
      const actualIntervals = detectedNotes.slice(1).map((note, index) =>
        (note.startTime - detectedNotes[index].startTime) / 1000);
      const rhythmMatches = Math.min(expectedIntervals.length, actualIntervals.length);
      const rhythmScore = rhythmMatches === 0 ? 0 : Math.round(
        actualIntervals.slice(0, rhythmMatches).reduce((sum, interval, index) =>
          sum + (Math.abs(interval - expectedIntervals[index]) <= 0.3 ? 1 : 0), 0) / rhythmMatches * 100,
      );
      setAnswerResult(isRu
        ? `Ноты: ${noteScore}% · Ритм: ${rhythmScore}% (${matched}/${expected.length} нот)`
        : `Notes: ${noteScore}% · Rhythm: ${rhythmScore}% (${matched}/${expected.length} notes)`);
    }
  }, [detectedNotes, isRecording, isRu, microphoneError, phrase, practiceBpm]);

  useEffect(() => () => {
    phraseTimers.current.forEach(window.clearTimeout);
    audioManager.stopBackingTrack();
    if (answerRecordingRef.current) stopRecording();
  }, [stopRecording]);

  const regeneratePhrase = useCallback(() => {
    setPhrase(generateEchoPhrase(activeChord, scaleId, level, `${Date.now()}-${Math.random()}`, targetPosition));
    setAnswerResult('');
  }, [activeChord, level, scaleId, targetPosition]);

  const handlePlayPhrase = async () => {
    phraseTimers.current.forEach(window.clearTimeout);
    phraseTimers.current = [];
    try {
      await Tone.start();
      setPhrasePlaying(true);
      let elapsedBeats = 0;
      phrase.forEach(note => {
        if (!note.isRest) {
          const time = Tone.now() + 0.05 + elapsedBeats * 60 / practiceBpm;
          audioManager.playGuitarNote(note.pitch, `${note.durationBeats * 60 / practiceBpm}s`, time, 0.75);
        }
        elapsedBeats += note.durationBeats;
      });
      phraseTimers.current.push(window.setTimeout(() => setPhrasePlaying(false), elapsedBeats * 60 / practiceBpm * 1000 + 100));
    } catch (error) {
      setAnswerResult(error instanceof Error ? error.message : String(error));
      setPhrasePlaying(false);
    }
  };

  const handleRecordAnswer = async () => {
    setAnswerResult('');
    if (isRecording) {
      stopRecording();
      return;
    }
    answerRecordingRef.current = true;
    wasRecordingRef.current = false;
    setRecordingAnswer(true);
    await startRecording();
  };

  const updateCustomChord = (index: number, chord: string) => {
    setPresetId('custom');
    setProgression(current => current.map((item, itemIndex) => itemIndex === index ? chord : item));
  };

  const currentScale = getScaleById(scaleId);
  const panelStyle: React.CSSProperties = {
    padding: '16px',
    borderRadius: '12px',
    border: '1px solid var(--border-color)',
    background: 'var(--bg-primary)',
    marginTop: '14px',
  };
  const selectStyle: React.CSSProperties = {
    minHeight: '40px',
    padding: '8px 12px',
    borderRadius: '8px',
    border: '1px solid var(--border-color)',
    background: 'var(--bg-panel)',
    color: 'var(--text-primary)',
    font: 'inherit',
  };
  const buttonStyle: React.CSSProperties = {
    minHeight: '40px',
    padding: '8px 14px',
    border: '1px solid var(--border-color)',
    borderRadius: '8px',
    background: 'var(--bg-panel)',
    color: 'var(--text-primary)',
    cursor: 'pointer',
    font: 'inherit',
    fontWeight: 700,
  };

  return (
    <section style={panelStyle} aria-label={isRu ? 'Режим тренировки импровизации' : 'Improvisation practice'}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
        <div>
          <h3 style={{ margin: 0, fontSize: 18 }}>{isRu ? 'Практика импровизации' : 'Improvisation practice'}</h3>
          <p style={{ margin: '5px 0 0', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
            {isRu
              ? 'Сначала выберите прогрессию и нажмите «Играть». На грифе смотрите только на синий корень и зелёные ноты аккорда.'
              : 'Choose a progression and press Play. On the fretboard, focus on the blue root and green chord tones.'}
          </p>
        </div>
        <label style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span>{isRu ? 'Уровень' : 'Level'}</span>
          <select value={level} onChange={event => setLevel(Number(event.target.value))} style={selectStyle} aria-label={isRu ? 'Уровень сложности' : 'Difficulty level'}>
            {[1, 2, 3, 4, 5].map(value => <option key={value} value={value}>{value}</option>)}
          </select>
        </label>
        <label style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span>{isRu ? 'Темп' : 'Tempo'}</span>
          <input
            type="number"
            min="40"
            max="220"
            value={practiceBpm}
            onChange={event => setPracticeBpm(Math.max(40, Math.min(220, Number(event.target.value) || 70)))}
            style={{ ...selectStyle, width: 82 }}
            aria-label={isRu ? 'Темп практики в ударах в минуту' : 'Practice tempo in beats per minute'}
          />
          <span>BPM</span>
        </label>
      </div>

      <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', alignItems: 'end', marginTop: 16 }}>
        <label style={{ display: 'grid', gap: 5, flex: '1 1 220px' }}>
          <span style={{ fontSize: 13, color: 'var(--text-secondary)' }}>{isRu ? '1. Выберите аккорды' : '1. Choose a progression'}</span>
          <select value={presetId} onChange={event => setPresetId(event.target.value)} style={selectStyle}>
            {PRESETS.map(preset => <option key={preset.id} value={preset.id}>{isRu ? preset.ru : preset.en}</option>)}
            {presetId === 'custom' && <option value="custom">{isRu ? 'Своя прогрессия' : 'Custom progression'}</option>}
          </select>
        </label>
        <label style={{ display: 'grid', gap: 5, minWidth: 130 }}>
          <span style={{ fontSize: 13, color: 'var(--text-secondary)' }}>
            {isRu ? `Громкость ${Math.round(backingLevel * 100)}%` : `Volume ${Math.round(backingLevel * 100)}%`}
          </span>
          <input
            type="range"
            min="0"
            max="1"
            step="0.05"
            value={backingLevel}
            onChange={event => setBackingLevel(Number(event.target.value))}
            aria-label={isRu ? 'Громкость гитарной подложки' : 'Guitar backing volume'}
          />
        </label>
        <span style={{ color: 'var(--text-secondary)', paddingBottom: 10 }}>
          {isRu ? 'Гитара + бас' : 'Guitar + bass'}
        </span>
        <button
          type="button"
          style={{ ...buttonStyle, background: isBackingPlaying ? 'var(--accent)' : undefined, color: isBackingPlaying ? '#101010' : undefined }}
          onClick={() => {
            setBackingError('');
            setIsBackingPlaying(value => !value);
          }}
          aria-pressed={isBackingPlaying}
        >
          {isBackingPlaying ? (isRu ? '■ Остановить' : '■ Stop') : (isRu ? '▶ Играть' : '▶ Play')}
        </button>
      </div>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center', marginTop: 10 }}>
        {progression.map((chord, index) => (
          <button
            type="button"
            key={`${index}-${chord}`}
            onClick={() => setActiveBar(index)}
            aria-pressed={activeBar === index}
            style={{
              ...buttonStyle,
              minWidth: 72,
              borderColor: activeBar === index ? 'var(--accent)' : 'var(--border-color)',
              color: activeBar === index ? 'var(--accent)' : 'var(--text-primary)',
            }}
          >
            {index + 1}. {chord}
          </button>
        ))}
        <label style={{ display: 'grid', gap: 5, minWidth: 130 }}>
          <span style={{ fontSize: 13, color: 'var(--text-secondary)' }}>
            {isRu ? 'Позиция грифа' : 'Fretboard position'}
          </span>
          <select value={targetPosition} onChange={event => onTargetPositionChange(Number(event.target.value))} style={selectStyle}>
            {[0, 5, 9, 12].map(position => (
              <option key={position} value={position}>
                {position === 0 ? (isRu ? 'Открытая · 0–4' : 'Open · 0–4') : `${position}–${position + 4}`}
              </option>
            ))}
          </select>
        </label>
        <button
          type="button"
          aria-expanded={isEditingProgression}
          onClick={() => setIsEditingProgression(value => !value)}
          style={buttonStyle}
        >
          {isEditingProgression ? (isRu ? 'Скрыть редактор' : 'Hide editor') : (isRu ? 'Изменить аккорды' : 'Edit chords')}
        </button>
      </div>
      {isEditingProgression && (
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 10 }}>
          {progression.map((chord, index) => (
            <label key={`edit-${index}-${chord}`} style={{ display: 'grid', gap: 5 }}>
              <span style={{ fontSize: 13, color: 'var(--text-secondary)' }}>{isRu ? `Такт ${index + 1}` : `Bar ${index + 1}`}</span>
              <select
                value={chord}
                onChange={event => updateCustomChord(index, event.target.value)}
                style={selectStyle}
                aria-label={isRu ? `Аккорд такта ${index + 1}` : `Chord for bar ${index + 1}`}
              >
                {Array.from(new Set([
                  chord,
                  ...NOTES.flatMap(note => [`${note}maj7`, `${note}m7b5`, `${note}m7`, `${note}7`, `${note}m`, note]),
                ])).map(option => <option key={option} value={option}>{option}</option>)}
              </select>
            </label>
          ))}
        </div>
      )}
      {backingError && <p role="alert" style={{ color: '#ff7777' }}>{backingError}</p>}

      <div style={{ marginTop: 16, padding: '12px 14px', borderRadius: 10, background: 'var(--bg-panel)' }}>
        <strong>{isRu ? '2. Текущий аккорд:' : '2. Current chord:'} {activeChord}</strong>
        <span style={{ marginLeft: 12, color: 'var(--text-secondary)' }}>
          {isRu ? `Такт ${activeBar + 1} из ${progression.length}` : `Bar ${activeBar + 1} of ${progression.length}`}
        </span>
        <div style={{ display: 'flex', gap: 7, flexWrap: 'wrap', marginTop: 10 }} aria-label={isRu ? 'Ноты аккорда' : 'Chord notes'}>
          {parsedChord?.intervals.map((interval, index) => (
            <span key={`${interval}-${index}`} style={{ padding: '6px 9px', borderRadius: 7, background: index === 0 ? '#58a6ff' : '#5ed58b', color: '#101216', fontWeight: 800 }}>
              {chordNoteNames[index]} <small>{CHORD_INTERVAL_LABELS[interval]}</small>
            </span>
          ))}
        </div>
        <p style={{ margin: '10px 0 0', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
          {isRu
            ? `Сначала попадите в зелёные ноты аккорда. На грифе показана одна позиция ${targetPosition}–${targetPosition + 4}; серые и внешние ноты скрыты.`
            : `Start with the green chord tones. The fretboard shows one position (${targetPosition}–${targetPosition + 4}); passing and outside notes are hidden.`}
        </p>
        <label style={{ display: 'inline-flex', alignItems: 'center', gap: 8, marginTop: 8, color: 'var(--text-secondary)' }}>
          <input
            type="checkbox"
            checked={showPassingNotes}
            onChange={event => onShowPassingNotesChange(event.target.checked)}
          />
          {isRu ? 'Показать проходящие ноты и напряжения' : 'Show passing notes and tensions'}
        </label>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 10 }}>
          {recommendations.map(recommendation => {
            const scale = getScaleById(recommendation.scaleId);
            return (
              <button
                type="button"
                key={scale.id}
                onClick={() => onScaleChange(scale.id, NOTES[parseChord(activeChord)?.root ?? 0])}
                style={{
                  ...buttonStyle,
                  borderColor: scaleId === scale.id ? 'var(--accent)' : 'var(--border-color)',
                  color: scaleId === scale.id ? 'var(--accent)' : 'var(--text-primary)',
                }}
                title={isRu ? recommendation.whyRu : recommendation.whyEn}
              >
                {scale.name}{scaleId === scale.id ? ' ✓' : ''}
              </button>
            );
          })}
        </div>
        <p style={{ margin: '10px 0 0', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
          {isRu ? recommendations.find(item => item.scaleId === scaleId)?.whyRu : recommendations.find(item => item.scaleId === scaleId)?.whyEn}
          {!recommendations.some(item => item.scaleId === scaleId) && (
            isRu ? ` ${currentScale.name}: ${currentScale.commonUse}.` : ` ${currentScale.name}: ${currentScale.commonUse}.`
          )}
        </p>
      </div>

      <div style={{ ...panelStyle, marginTop: 12 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
          <div>
            <h4 style={{ margin: 0 }}>{isRu ? 'Эхо-фраза' : 'Echo phrase'}</h4>
            <p style={{ margin: '5px 0 0', color: 'var(--text-secondary)' }}>
              {isRu ? `Уровень ${level} · ${activeChord} · ${currentScale.name}` : `Level ${level} · ${activeChord} · ${currentScale.name}`}
            </p>
          </div>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            <button type="button" style={buttonStyle} onClick={regeneratePhrase}>
              {isRu ? '↻ Новая фраза' : '↻ New phrase'}
            </button>
            <button type="button" style={buttonStyle} onClick={handlePlayPhrase} disabled={phrasePlaying}>
              {phrasePlaying ? (isRu ? 'Играет…' : 'Playing…') : (isRu ? '▶ Слушать' : '▶ Hear phrase')}
            </button>
            <button
              type="button"
              style={{ ...buttonStyle, background: isRecording ? '#e65f5f' : undefined }}
              onClick={handleRecordAnswer}
            >
              {isRecording ? (isRu ? '■ Завершить запись' : '■ Finish recording') : (isRu ? '🎙 Записать ответ' : '🎙 Record answer')}
            </button>
          </div>
        </div>
        <div style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 8, marginTop: 14 }} aria-label={isRu ? 'Ноты фразы' : 'Phrase notes'}>
          {phrase.map((note, index) => (
            <span key={`${index}-${note.pitch || 'rest'}`} style={{ display: 'inline-flex', flexDirection: 'column', minWidth: 48, alignItems: 'center', padding: '7px 10px', borderRadius: 8, background: 'var(--bg-secondary)' }}>
              <strong>{note.isRest ? (isRu ? 'Пауза' : 'Rest') : note.pitch}</strong>
              {!note.isRest && <small style={{ color: 'var(--text-secondary)' }}>{isRu ? `стр. ${note.string + 1} · лад ${note.fret}` : `str. ${note.string + 1} · fret ${note.fret}`}</small>}
            </span>
          ))}
        </div>
        <p style={{ margin: '12px 0 0', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
          {isRu
            ? 'Микрофон включается только после нажатия «Записать ответ». Сыграйте фразу, затем завершите запись для проверки нот и ритма.'
            : 'The microphone is requested only after you press “Record answer”. Play the phrase, then finish recording to check notes and rhythm.'}
        </p>
        {recordingAnswer && <p role="status">{isRu ? 'Слушаю микрофон…' : 'Listening to the microphone…'}</p>}
        {answerResult && <p role="status" style={{ marginBottom: 0, color: 'var(--accent)', fontWeight: 700 }}>{answerResult}</p>}
      </div>

      <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginTop: 12, fontSize: 13 }}>
        {[
          ['root', '#58a6ff', '●'],
          ['chordTone', '#5ed58b', '■'],
          ...(showPassingNotes ? [['tension', '#f4c95d', '◇'], ['passing', '#a8afb9', '○']] : []),
        ].map(([role, color, marker]) => (
          <span key={role} style={{ color: String(color) }}>
            <span aria-hidden="true">{marker}</span> {getRoleLabel(String(role), locale)}
          </span>
        ))}
      </div>
    </section>
  );
};

export default PracticeMode;
