import type {
  BassBeatEvent,
  ChordBeatEvent,
  DrumBeatEvent,
  FretLabArrangement,
  MelodyBeatEvent,
} from '../types/song';

export function totalArrangementBeats(arrangement: FretLabArrangement): number {
  return arrangement.bars * arrangement.timeSignature.beats;
}

export function getEventsAtBeat<T extends { beatStart: number; durationBeats: number }>(
  events: T[],
  beat: number,
): T[] {
  return events.filter(event => event.beatStart <= beat && event.beatStart + event.durationBeats > beat);
}

export function validateArrangement(arrangement: FretLabArrangement): string[] {
  const errors: string[] = [];
  const totalBeats = totalArrangementBeats(arrangement);

  const validate = (events: Array<ChordBeatEvent | MelodyBeatEvent | BassBeatEvent | DrumBeatEvent>) => {
    events.forEach(event => {
      if (!Number.isFinite(event.beatStart) || event.beatStart < 0) {
        errors.push(`${event.track}: invalid beatStart`);
      }
      if (!Number.isFinite(event.durationBeats) || event.durationBeats <= 0) {
        errors.push(`${event.track}: invalid durationBeats`);
      }
      if (event.beatStart + event.durationBeats > totalBeats + 0.001) {
        errors.push(`${event.track}: event exceeds arrangement length`);
      }
    });
  };

  validate(arrangement.chords);
  validate(arrangement.melody);
  validate(arrangement.bass);
  validate(arrangement.drums);

  if (!arrangement.sections.length) {
    errors.push('No arrangement sections');
  }

  return errors;
}
