import type { FretLabArrangement, ChordBeatEvent } from '../types/song';

export interface MusicContextEngineInput {
  key: string;
  mode: string;
  bpm: number;
  timeSignature: FretLabArrangement['timeSignature'];
  bars: number;
  chords: ChordBeatEvent[];
}

export function buildMusicContext(arrangement: FretLabArrangement): MusicContextEngineInput {
  return {
    key: arrangement.key,
    mode: arrangement.mode,
    bpm: arrangement.bpm,
    timeSignature: arrangement.timeSignature,
    bars: arrangement.bars,
    chords: arrangement.chords,
  };
}
