import { CHORD_LIBRARY } from '../data/chordLibrary';

// Словарь соответствия нот и их позиции в полутонах (от 0 до 11)
// Учитываем и диезы (#), и бемоли (b)
const NOTE_TO_SEMITONE: Record<string, number> = {
  'CB': -1, 'C': 0, 'C#': 1, 'DB': 1, 'D': 2, 'D#': 3, 'EB': 3, FB: 4,
  'E': 4, 'F': 5, 'F#': 6, 'GB': 6, 'G': 7, 'G#': 8, 'AB': 8,
  'A': 9, 'A#': 10, 'BB': 10, 'B': 11, 'B#': 12
};

// Извлекаем корневую ноту из строки аккорда ("Bbm7" → "Bb", "F#" → "F#")
function extractRootNote(key: string): string {
  const upper = key.toUpperCase();
  // Сначала пробуем двухсимвольные (диез/бемоль): C#, Db, Eb, F#, Gb, Ab, Bb, B#
  const twoChar = upper.match(/^[A-G][#b]/);
  if (twoChar) return twoChar[0];
  // Иначе — одиночная нота
  const oneChar = upper.match(/^[A-G]/);
  return oneChar ? oneChar[0] : '';
}

/**
 * Вычисляет идеальный сдвиг в полутонах между двумя нотами/аккордами.
 * Ищет кратчайший путь, чтобы избежать сильных искажений звука (эффекта "бурундука").
 */
export function calculatePitchShift(baseKey: string, targetKey: string): number {
  // Берем только корневую ноту (аккорды вида "Am7", "Bbmaj7", "F#" → "A", "Bb", "F#")
  const cleanBase = extractRootNote(baseKey);
  const cleanTarget = extractRootNote(targetKey);

  const baseVal = NOTE_TO_SEMITONE[cleanBase] ?? 0;
  const targetVal = NOTE_TO_SEMITONE[cleanTarget] ?? 0;

  let diff = targetVal - baseVal;

  // ОПТИМИЗАЦИЯ ПИТЧА:
  // Если мы идем из C (0) в B (11), разница = +11 полутонов. Звук будет искажен.
  // Логичнее опустить C на -1 полутон.
  if (diff > 6) {
    diff -= 12;
  }
  if (diff < -5) {
    diff += 12;
  }

  return diff;
}

// Экспортируем ту же самую функцию под вторым именем.
// Теперь неважно, импортируете вы calculatePitchShift или calculateTranspose —
// TypeScript будет доволен в обоих случаях.
export { calculatePitchShift as calculateTranspose };

export interface ParsedChord {
  rootName: string;
  root: number;
  quality: string;
  intervals: number[];
}

export function pitchClassOf(note: string): number | null {
  const normalized = note.replace(/♯/g, '#').replace(/♭/g, 'b');
  const value = NOTE_TO_SEMITONE[normalized.toUpperCase()];
  return value === undefined ? null : ((value % 12) + 12) % 12;
}

export function parseChord(chordName: string): ParsedChord | null {
  const match = chordName.match(/^([A-G](?:#|b)?)(.*)$/i);
  if (!match) return null;
  const rootName = match[1][0].toUpperCase() + match[1].slice(1);
  const root = pitchClassOf(rootName);
  if (root === null) return null;
  const quality = match[2].toLowerCase().replace(/\s/g, '');
  const libraryDefinition = CHORD_LIBRARY[chordName];

  let intervals = libraryDefinition?.intervals;
  if (!intervals) {
    if (quality.includes('m7b5') || quality.includes('ø')) intervals = [0, 3, 6, 10];
    else if (quality.includes('dim7') || quality.includes('°7')) intervals = [0, 3, 6, 9];
    else if (quality.includes('dim') || quality.includes('°')) intervals = [0, 3, 6];
    else if (quality.includes('mmaj7') || quality.includes('m(maj7)')) intervals = [0, 3, 7, 11];
    else if (quality.includes('maj7')) intervals = [0, 4, 7, 11];
    else if (quality === 'maj9' || quality === 'maj11' || quality === 'maj13') intervals = [0, 4, 7, 11];
    else if (quality.includes('m7') || quality.startsWith('m')) intervals = [0, 3, 7, 10];
    else if (quality.includes('7')) intervals = [0, 4, 7, 10];
    else if (quality.includes('aug') || quality.includes('+')) intervals = [0, 4, 8];
    else if (quality.includes('sus4')) intervals = [0, 5, 7];
    else if (quality.includes('sus2')) intervals = [0, 2, 7];
    else if (quality === '' || quality === 'maj' || quality === 'major') intervals = [0, 4, 7];
    else return null;
  }

  return { rootName, root, quality, intervals };
}