export const getChordScaleRecommendations = (quality: string): ChordScaleRecommendation[] => {
  const normalized = quality.toLowerCase();
  if (normalized.includes('alt') || normalized.includes('b9') || normalized.includes('#9')) return CHORD_SCALE_MAP['7alt'];
  if (normalized.includes('m7b5') || normalized.includes('ø')) return CHORD_SCALE_MAP.m7b5;
  if (normalized.includes('dim7') || normalized.includes('°7')) return CHORD_SCALE_MAP.dim7;
  if (normalized.includes('mmaj7') || normalized.includes('m(maj7)')) return CHORD_SCALE_MAP.mMaj7;
  if (normalized.includes('maj7')) return CHORD_SCALE_MAP.maj7;
  if (normalized.includes('m7') || /m(?:in)?$/.test(normalized)) return CHORD_SCALE_MAP.m7;
  if (normalized.includes('7')) return CHORD_SCALE_MAP['7'];
  return CHORD_SCALE_MAP.maj7;
};
