// src/components/layout/AppShell.tsx

import { useState, useEffect, useCallback } from 'react';
import type React from 'react';
import Header from './Header';
import Player from '../player/Player';
import CircleOfFifths from '../tools/CircleOfFifths';
import Fretboard from '../fretboard/Fretboard';
import Tablature from '../fretboard/Tablature';
import DiatonicChords from '../tools/DiatonicChords';
import ChordDictionary from '../tools/ChordDictionary';
import SoloGenerator from '../tools/SoloGenerator';
import EarTrainer from '../tools/EarTrainer';
import RecordingAnalyzer from '../tools/RecordingAnalyzer';
import PracticeDashboard from '../PracticeDashboard';
import GameRoom from '../GameRoom/GameRoom';
import SEOHead from '../SEOHead';
import { RigPanel } from '../FretLabRig/RigPanel';
import { useMusic } from '../../context/MusicContext';
import { useTranslation } from '../../context/LocaleContext';

type ModuleType = 'engine' | 'dictionary' | 'autotab' | 'rig' | 'practice' | 'gameroom' | 'earTrainer' | 'phraseDetector';

const AppShell: React.FC = () => {
  const { t, locale } = useTranslation();
  const [activeModule, setActiveModule] = useState<ModuleType>('engine');
  const [aiTargetChord, setAiTargetChord] = useState<string | null>(null);
  const [isTransitioning, setIsTransitioning] = useState(false);

  const { setBpm } = useMusic();

  const handleAIAction = useCallback((action: any) => {
    if (!action) return;

    console.log('🔊 AppShell received action:', action);

    const switchModule = (module: ModuleType) => {
      setIsTransitioning(true);
      setTimeout(() => {
        setActiveModule(module);
        setTimeout(() => setIsTransitioning(false), 300);
      }, 200);
    };

    switch (action.type) {
      case 'SET_BPM':
        if (action.payload?.bpm) {
          setBpm(action.payload.bpm);
          console.log('🎵 BPM set to:', action.payload.bpm);
        }
        break;

      case 'OPEN_CHORD':
        setAiTargetChord(action.payload?.chord || null);
        switchModule('dictionary');
        break;

case 'OPEN_ENGINE':
        switchModule('engine');
        break;

      case 'OPEN_TAB_GEN':
      case 'OPEN_AUTOTAB':
        switchModule('autotab');
        break;

      case 'OPEN_PRACTICE':
        switchModule('practice');
        break;

      case 'OPEN_RIG':
        switchModule('rig');
        break;

      case 'SEARCH_BACKING':
      case 'SEARCH_YOUTUBE':
        switchModule('engine');
        {
          const ytQuery = encodeURIComponent(action.payload?.query || 'guitar backing track');
          window.open(`https://www.youtube.com/results?search_query=${ytQuery}`, '_blank', 'noopener,noreferrer');
        }
        break;

      case 'SEARCH_VK':
        {
          const vkQuery = encodeURIComponent(action.payload?.query || '');
          window.open(`https://vk.com/video?q=${vkQuery}`, '_blank', 'noopener,noreferrer');
        }
        break;

      case 'SEARCH_RUTUBE':
        {
          const ruQuery = encodeURIComponent(action.payload?.query || '');
          window.open(`https://rutube.ru/search/?query=${ruQuery}`, '_blank', 'noopener,noreferrer');
        }
        break;

      case 'SET_CONTEXT':
        console.log('🎯 Setting context:', action.payload);
        break;

      default:
        console.warn('⚠️ Unknown action type:', action.type);
    }
  }, [setBpm]);

  useEffect(() => {
    const handleKeyPress = (e: KeyboardEvent) => {
if ((e.ctrlKey || e.metaKey) && e.key >= '1' && e.key <= '8') {
        e.preventDefault();
        const modules: ModuleType[] = ['engine', 'dictionary', 'autotab', 'rig', 'practice', 'gameroom', 'earTrainer', 'phraseDetector'];
        const index = parseInt(e.key) - 1;
        if (index < modules.length) {
          setActiveModule(modules[index]);
        }
      }
      if (e.key === 'Escape') {
        setAiTargetChord(null);
      }
    };

    window.addEventListener('keydown', handleKeyPress);
    return () => window.removeEventListener('keydown', handleKeyPress);
  }, []);

  const handleModuleClick = (module: ModuleType) => {
    setActiveModule(module);
  };

  const NAV_MODULES: Record<ModuleType, { icon: string; title: string; mobileTitle: string }> = {
    engine: { icon: '🎸', title: t.nav.fretboard, mobileTitle: locale === 'ru' ? 'Гриф' : 'Fretboard' },
    dictionary: { icon: '◆', title: t.nav.dictionary, mobileTitle: locale === 'ru' ? 'Аккорды' : 'Chords' },
    autotab: { icon: '♫', title: t.nav.autotab, mobileTitle: locale === 'ru' ? 'Соло' : 'Solo' },
    rig: { icon: '≋', title: t.nav.rig, mobileTitle: locale === 'ru' ? 'Риг' : 'Rig' },
    practice: { icon: '⌁', title: t.nav.practice, mobileTitle: locale === 'ru' ? 'Практика' : 'Practice' },
    gameroom: { icon: '▦', title: t.nav.gameroom, mobileTitle: locale === 'ru' ? 'Игры' : 'Games' },
    earTrainer: { icon: '🎧', title: t.nav.earTrainer, mobileTitle: locale === 'ru' ? 'Слух' : 'Ear' },
    phraseDetector: { icon: '🎙', title: t.nav.phraseDetector, mobileTitle: locale === 'ru' ? 'Фразы' : 'Phrases' },
  };

  const pageDescriptions: Record<ModuleType, string> = locale === 'ru'
    ? {
      engine: 'Изучайте ноты и гаммы на грифе, настраивайте тональность и сразу слышите результат.',
      dictionary: 'Находите аппликатуры, сравнивайте варианты и собирайте аккорды для своей музыки.',
      autotab: 'Создавайте гитарные фразы и аранжировки, настраивая стиль, гармонию и звучание.',
      rig: 'Соберите цепочку эффектов и настройте звучание гитары под свой стиль.',
      practice: 'Планируйте занятия, отслеживайте прогресс и возвращайтесь к своим целям.',
      gameroom: 'Сделайте паузу и выберите браузерную игру из коллекции FretLab.',
      earTrainer: 'Тренируйте слух: распознавайте ноты, интервалы, мелодии и аккорды.',
      phraseDetector: 'Запишите сыгранную фразу и разберите её ноты, интонацию и ритм.',
    }
    : {
      engine: 'Explore notes and scales across the fretboard, choose a key, and hear what you are learning.',
      dictionary: 'Find chord voicings, compare shapes, and build a vocabulary for your music.',
      autotab: 'Create guitar phrases and arrangements, then shape the style, harmony, and sound.',
      rig: 'Build an effects chain and shape your guitar tone to fit the way you play.',
      practice: 'Plan focused sessions, keep track of progress, and return to your goals.',
      gameroom: 'Take a break and choose a browser game from the FretLab collection.',
      earTrainer: 'Train your ear by identifying notes, intervals, melodies, and chords.',
      phraseDetector: 'Record a phrase and review its notes, intonation, and rhythm.',
    };

  const renderNavIcon = (module: ModuleType) => {
    const isActive = activeModule === module;
    const config = NAV_MODULES[module];

    return (
      <button
        type="button"
        className={`bottom-nav-item${isActive ? ' bottom-nav-item--active' : ''}`}
        aria-label={config.title}
        aria-current={isActive ? 'page' : undefined}
        title={config.title}
        onClick={() => handleModuleClick(module)}
      >
        <span className="bottom-nav-item__icon" aria-hidden="true">{config.icon}</span>
        <span className="bottom-nav-item__label">
          <span className="bottom-nav-item__full-label">{config.title}</span>
          <span className="bottom-nav-item__mobile-label">{config.mobileTitle}</span>
        </span>
      </button>
    );
  };

  // Вертикальный поток: все блоки идут последовательно без колонок
  const renderContent = (): React.ReactNode => {
    switch (activeModule) {
      case 'engine':
        return (
          <main className="center-column">
            <section className="page-context" aria-label={NAV_MODULES.engine.title}>
              <p className="page-context__eyebrow">{NAV_MODULES.engine.title}</p>
              <p className="page-context__description">{pageDescriptions.engine}</p>
            </section>
            <div className="engine-page-layout">
              <div className="engine-page-layout__main">
                <Player />
                <div className="fretboard-scroll-wrapper">
                  <Fretboard />
                </div>
                <Tablature />
              </div>
              <aside className="engine-page-layout__side">
                <CircleOfFifths />
                <DiatonicChords />
              </aside>
            </div>
          </main>
        );

case 'dictionary':
        return (
          <main className="center-column">
            <section className="page-context" aria-label={NAV_MODULES.dictionary.title}>
              <p className="page-context__eyebrow">{NAV_MODULES.dictionary.title}</p>
              <p className="page-context__description">{pageDescriptions.dictionary}</p>
            </section>
            <ChordDictionary targetChord={aiTargetChord} />
          </main>
        );

      case 'autotab':
        return (
          <main className="center-column">
            <section className="page-context" aria-label={NAV_MODULES.autotab.title}>
              <p className="page-context__eyebrow">{NAV_MODULES.autotab.title}</p>
              <p className="page-context__description">{pageDescriptions.autotab}</p>
            </section>
            <SoloGenerator />
          </main>
        );

      case 'rig':
        return (
          <main className="center-column">
            <section className="page-context" aria-label={NAV_MODULES.rig.title}>
              <p className="page-context__eyebrow">{NAV_MODULES.rig.title}</p>
              <p className="page-context__description">{pageDescriptions.rig}</p>
            </section>
            <RigPanel />
          </main>
        );

      case 'practice':
        return (
          <main className="center-column">
            <section className="page-context" aria-label={NAV_MODULES.practice.title}>
              <p className="page-context__eyebrow">{NAV_MODULES.practice.title}</p>
              <p className="page-context__description">{pageDescriptions.practice}</p>
            </section>
            <PracticeDashboard />
          </main>
        );

      case 'gameroom':
        return (
          <main className="center-column">
            <section className="page-context" aria-label={NAV_MODULES.gameroom.title}>
              <p className="page-context__eyebrow">{NAV_MODULES.gameroom.title}</p>
              <p className="page-context__description">{pageDescriptions.gameroom}</p>
            </section>
            <GameRoom />
          </main>
        );

      case 'earTrainer':
        return (
          <main className="center-column">
            <section className="page-context" aria-label={NAV_MODULES.earTrainer.title}>
              <p className="page-context__eyebrow">{NAV_MODULES.earTrainer.title}</p>
              <p className="page-context__description">{pageDescriptions.earTrainer}</p>
            </section>
            <EarTrainer />
          </main>
        );

      case 'phraseDetector':
        return (
          <main className="center-column">
            <section className="page-context" aria-label={NAV_MODULES.phraseDetector.title}>
              <p className="page-context__eyebrow">{NAV_MODULES.phraseDetector.title}</p>
              <p className="page-context__description">{pageDescriptions.phraseDetector}</p>
            </section>
            <RecordingAnalyzer />
          </main>
        );

      default:
        return null;
    }
  };

const seoByModule: Record<ModuleType, { title: string; description: string; keywords: string }> = {
    engine: {
      title: t.seo.engineTitle,
      description: t.seo.engineDesc,
      keywords: 'fretboard, guitar, notes, scales, гриф гитары, ноты на грифе',
    },
dictionary: {
      title: t.seo.dictionaryTitle,
      description: t.seo.dictionaryDesc,
      keywords: 'chords, guitar chords, аккорды для гитары, аппликатуры',
    },
    autotab: {
      title: t.seo.autotabTitle,
      description: t.seo.autotabDesc,
      keywords: 'ai solo generator, tab generator, гитарное соло онлайн, ai музыка',
    },
    rig: {
      title: t.seo.rigTitle,
      description: t.seo.rigDesc,
      keywords: 'guitar rig, педали эффектов, гитарный процессор, дисторшн, ревербератор',
    },
    practice: {
      title: t.seo.practiceTitle,
      description: t.seo.practiceDesc,
      keywords: 'guitar practice, тренировки для гитары, обучение гитаре, уроки гитары',
    },
    gameroom: {
      title: t.seo.gameroomTitle,
      description: t.seo.gameroomDesc,
      keywords: 'browser games, игры онлайн, игровая комната, ретро игры',
    },
    earTrainer: {
      title: t.seo.earTrainerTitle,
      description: t.seo.earTrainerDesc,
      keywords: 'ear training, music ear trainer, тренажёр слуха, музыкальный слух',
    },
    phraseDetector: {
      title: t.seo.phraseDetectorTitle,
      description: t.seo.phraseDetectorDesc,
      keywords: 'guitar phrase analysis, phrase detector, анализ гитарной фразы, детектор фраз',
    },
  };

  const currentSeo = seoByModule[activeModule];

  return (
    <div className="app-container">
      <SEOHead
        title={currentSeo.title}
        description={currentSeo.description}
        keywords={currentSeo.keywords}
        ogTitle={`${currentSeo.title} | FretLab`}
        ogDescription={currentSeo.description}
      />
      <Header onAIAction={handleAIAction} />

      <div className="app-main">
        <div className="app-layout">
          <div className={`main-workspace main-workspace--${activeModule}${isTransitioning ? ' transitioning' : ''}`}>
            {renderContent()}
          </div>

          <nav className="bottom-nav" aria-label={locale === 'ru' ? 'Основная навигация' : 'Main navigation'}>
{renderNavIcon('engine')}
            {renderNavIcon('dictionary')}
            {renderNavIcon('autotab')}
            {renderNavIcon('rig')}
            {renderNavIcon('practice')}
            {renderNavIcon('gameroom')}
            {renderNavIcon('earTrainer')}
            {renderNavIcon('phraseDetector')}
            <div className="sidebar-footer desktop-only">
              <span className="version-text">v2.0.0</span>
              <span className="shortcut-text">Ctrl+1-8</span>
            </div>
          </nav>
        </div>
      </div>
    </div>
  );
};

export default AppShell;
