export type ScaleFamily =
  | 'foundation'
  | 'major-modes'
  | 'melodic-minor'
  | 'harmonic-minor'
  | 'symmetric'
  | 'world'
  | 'bebop'
  | 'arpeggio';

export type ScaleMood = 'bright' | 'dark' | 'tense' | 'neutral';

export interface ScaleDefinition {
  id: string;
  name: string;
  family: ScaleFamily;
  intervals: number[];
  mood: ScaleMood;
  difficulty: 1 | 2 | 3 | 4 | 5;
  commonUse: string;
  recommendedChords: string[];
  pentatonic?: boolean;
}

